examples.template:
let shown = domains.filter { query.isEmpty || $0.name.contains(query.lowercased()) }
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            MonarchTableToolbar(resultCount: shown.count) {
                HStack(spacing: MonarchTokens.Space.space2) {
                    MonarchTextField("Search", text: $query, prompt: "Search...", labelVisibility: .hidden) {
                        MonarchIcon(systemName: "magnifyingglass", size: .sm).accessibilityHidden(true)
                    } trailing: {
                        EmptyView()
                    }
                    .frame(minWidth: MonarchTokens.Space.space24 * 2)
                    MonarchButton({{filter}}, variant: .secondary, size: .sm) {}
                }
            } controls: {
                MonarchSegmentedControl(
                    {{columnsLabel}},
                    selection: $view,
                    items: [
                        MonarchSegmentedItem({{viewLabels.0}}, value: {{views.0}}, systemImage: "tablecells"),
                        MonarchSegmentedItem({{viewLabels.1}}, value: {{views.1}}, systemImage: "rectangle.3.group"),
                    ],
                    size: .sm,
                    fillsWidth: false
                )
                MonarchButton({{columnsLabel}}, systemImage: "rectangle.split.3x1", variant: .secondary, size: .sm) {}
                MonarchButton({{action}}, variant: .secondary, size: .sm) {}
            }
            MonarchDataTable(
                {{caption}},
                rows: shown,
                columns: [
                    MonarchDataTableColumn({{columns.0}}, isHideable: false) { $0.name },
                    MonarchDataTableColumn({{columns.1}}) { $0.status },
                    MonarchDataTableColumn({{columns.2}}) { $0.owner },
                ],
                selection: $selected,
                layout: .list
            )
            .frame(height: 380)
        }
    }
}

