let shown = domains.filter { query.isEmpty || $0.name.contains(query.lowercased()) }
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            MonarchTableToolbar(resultCount: shown.count) {
                HStack(spacing: MonarchTokens.Space.space2) {
                    MonarchTextField("Search", text: $query, prompt: "Search...", labelVisibility: .hidden) {
                        MonarchIcon(systemName: "magnifyingglass", size: .sm).accessibilityHidden(true)
